import { Hono } from 'hono';
import { PreferencesSchema } from '@praxis/protocol';
import type { AdapterBundle } from '../../contracts.js';
import { session } from '../../session.js';

export function registerPreferencesRoutes(app: Hono, adapters: AdapterBundle): void {
  app.post('/v1/preferences', async (c) => {
    const preferences = PreferencesSchema.parse(await c.req.json());
    await adapters.store.putPreferences(session(c).userId, preferences);
    return c.json({ ok: true });
  });
}
